head.b:skin:
/* ═══════════════════════════════════════════════════════════════════
   SCRIPTVAULT BLOGGER THEME - MASTER STYLESHEET
   Palette: Pure Black (#000000), Cyan (#00e5ff), Purple (#a855f7)
   Performance: Zero backdrop-filter, zero infinite animations, GPU optimized
   ═══════════════════════════════════════════════════════════════════ */

:root {
    --bg-color: #000000;
    --card-bg: #0c0c14;
    --card-bg-gradient: linear-gradient(135deg, #0c0c14 0%, #08080e 100%);
    --accent-cyan: #00e5ff;
    --accent-purple: #a855f7;
    --text-main: #ffffff;
    --text-muted: #b8b8c8;
    --border-cyan: rgba(0, 229, 255, 0.12);
    --border-cyan-hover: rgba(0, 229, 255, 0.28);
    --font-main: 'Inter', sans-serif;
    --font-heading: 'Orbitron', sans-serif;
    --font-code: 'JetBrains Mono', monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: var(--font-main);
    font-weight: 500;
    line-height: 1.6;
    overflow-x: hidden;
    selection-background-color: var(--accent-cyan);
    selection-color: var(--bg-color);
}

::selection {
    background: var(--accent-cyan);
    color: var(--bg-color);
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
}
::-webkit-scrollbar-track {
    background: var(--bg-color);
}
::-webkit-scrollbar-thumb {
    background: rgba(0, 229, 255, 0.3);
    border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--accent-cyan);
}

/* Ambient Background & Grid (Static) */
.ambient-bg {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: 
        radial-gradient(circle at 10% 20%, rgba(0, 229, 255, 0.04) 0%, transparent 40%),
        radial-gradient(circle at 90% 80%, rgba(168, 85, 247, 0.04) 0%, transparent 40%);
    z-index: -2;
    pointer-events: none;
}

.grid-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: linear-gradient(rgba(0, 229, 255, 0.015) 1px, transparent 1px),
                      linear-gradient(90deg, rgba(0, 229, 255, 0.015) 1px, transparent 1px);
    background-size: 40px 40px;
    z-index: -1;
    pointer-events: none;
}

/* Header Navbar (Sticky) */
header.site-header {
    position: sticky;
    top: 0;
    z-index: 1000;
    background-color: rgba(0, 0, 0, 0.92);
    border-bottom: 1px solid var(--border-cyan);
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 2rem;
    contain: layout style paint;
}

.logo-container {
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none;
}

.logo-container svg {
    width: 32px;
    height: 32px;
    fill: var(--accent-cyan);
    filter: drop-shadow(0 0 8px rgba(0, 229, 255, 0.4));
}

.logo-text {
    font-family: var(--font-heading);
    font-size: 1.4rem;
    font-weight: 900;
    color: var(--text-main);
    text-transform: uppercase;
    letter-spacing: 1px;
    text-shadow: 0 0 10px rgba(0, 229, 255, 0.5);
}

.nav-menu {
    display: flex;
    gap: 24px;
    list-style: none;
}

.nav-menu a {
    color: var(--text-muted);
    text-decoration: none;
    font-weight: 700;
    font-size: 0.95rem;
    transition: color 0.2s ease;
}

.nav-menu a:hover {
    color: var(--accent-cyan);
    text-shadow: 0 0 8px rgba(0, 229, 255, 0.4);
}

/* Main Container & Layout */
.site-main-wrap {
    max-width: 1300px;
    margin: 2rem auto;
    padding: 0 1.5rem;
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 2rem;
}

@media (max-width: 900px) {
    .site-main-wrap {
        grid-template-columns: 1fr;
    }
}

/* Post Cards */
.post-card {
    background: var(--card-bg-gradient);
    border: 1px solid var(--border-cyan);
    border-radius: 12px;
    padding: 1.8rem;
    margin-bottom: 1.5rem;
    position: relative;
    overflow: hidden;
    contain: layout style paint;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.post-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.post-title {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 800;
    margin-bottom: 0.8rem;
}

.post-title a {
    color: var(--text-main);
    text-decoration: none;
    text-shadow: 0 0 10px rgba(0, 229, 255, 0.3);
    transition: color 0.2s;
}

.post-title a:hover {
    color: var(--accent-cyan);
}

.post-meta {
    font-size: 0.85rem;
    color: var(--text-muted);
    margin-bottom: 1rem;
}

.post-snippet {
    color: var(--text-muted);
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
}

.post-footer-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
}

.btn-readmore {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-purple));
    color: var(--bg-color);
    padding: 0.6rem 1.4rem;
    font-family: var(--font-heading);
    font-weight: 800;
    font-size: 0.85rem;
    text-decoration: none;
    border-radius: 6px;
    text-transform: uppercase;
    box-shadow: 0 0 12px rgba(0, 229, 255, 0.25);
}

.labels-list {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
}

.label-pill {
    background: rgba(0, 229, 255, 0.06);
    border: 1px solid var(--border-cyan);
    color: var(--accent-cyan);
    padding: 0.2rem 0.6rem;
    font-size: 0.75rem;
    font-weight: 700;
    border-radius: 4px;
    text-decoration: none;
}

/* Sidebar Widgets */
aside.sidebar {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.widget {
    background: var(--card-bg-gradient);
    border: 1px solid var(--border-cyan);
    border-radius: 12px;
    padding: 1.5rem;
    position: relative;
    overflow: hidden;
    contain: layout style paint;
}

.widget::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));
}

.widget h2, .widget h3 {
    font-family: var(--font-heading);
    font-size: 1.1rem;
    font-weight: 800;
    text-transform: uppercase;
    color: var(--text-main);
    margin-bottom: 1rem;
    text-shadow: 0 0 8px rgba(0, 229, 255, 0.4);
    border-bottom: 1px solid var(--border-cyan);
    padding-bottom: 0.5rem;
}

.widget ul {
    list-style: none;
}

.widget ul li {
    margin-bottom: 0.6rem;
}

.widget ul li a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.9rem;
    transition: color 0.2s;
}

.widget ul li a:hover {
    color: var(--accent-cyan);
}

/* Pagination */
.blog-pager {
    display: flex;
    justify-content: space-between;
    margin: 2rem 0;
}

.blog-pager-older-link, .blog-pager-newer-link {
    background: var(--card-bg);
    border: 1px solid var(--border-cyan);
    color: var(--accent-cyan);
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    text-decoration: none;
    font-family: var(--font-heading);
    font-weight: 800;
    font-size: 0.85rem;
}

/* Footer */
footer.site-footer {
    text-align: center;
    padding: 2.5rem 1rem;
    border-top: 1px solid var(--border-cyan);
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-top: 3rem;
}

footer.site-footer a {
    color: var(--accent-cyan);
    text-decoration: none;
    font-weight: 700;
}

/* Badge Dot Pulse (The only permitted infinite animation) */
@keyframes pulseDot {
    0% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.4; transform: scale(0.85); }
    100% { opacity: 1; transform: scale(1); }
}
.pulse-dot {
    width: 8px;
    height: 8px;
    background-color: var(--accent-cyan);
    border-radius: 50%;
    display: inline-block;
    animation: pulseDot 1.8s infinite ease-in-out;
}
